function bookPageLinks(page){return (bookPageUnits[page]||[]).map(key=>{const [ch,id]=key.split('/'),u=bookUnits.find(u=>u.chapter===Number(ch)&&u.id===id);return u?`<a href="${bookHref(u)}">第 ${ch} 章 · ${u.title} ↗</a>`:''}).join('；')}
